        getHint(state, results) {
            if (!results) return null;
            // Diagnostics first. NOTE: littleRatio is the Little's-Law identity WIP/(TH*CT),
            // which is always ~1.0 by construction, so it must not gate the actionable hints.
            if (results.efficiency < 50) {
                return window.mySimulation.t('hint_low_eff');
            }
            if (results.block1 > 0.15 || results.block2 > 0.15) {
                return window.mySimulation.t('hint_blocking');
            }
            if (results.starv2 > 0.15 || results.starv3 > 0.15) {
                return window.mySimulation.t('hint_starvation');
            }
            if (state.decisions && state.decisions.conwip === 'off' && results.wip > 12) {
                return window.mySimulation.t('hint_try_conwip');
            }
            if (results.efficiency > 90) {
                return window.mySimulation.t('hint_high_eff');
            }
            if (results.efficiency >= 75 && results.littleRatio && Math.abs(results.littleRatio - 1.0) < 0.02) {
                return window.mySimulation.t('hint_little_ok');
            }
            return window.mySimulation.t('hint_keep_testing');
        }

