        getPerformanceSummary(history) {
            if (!history.length) return {};
            const effs = history.map(r => (r.results && r.results.efficiency) || 0);
            const throughputs = history.map(r => (r.results && r.results.throughput) || 0);
            const wips = history.map(r => (r.results && r.results.wip) || 0);
            const bestEff = Math.max.apply(null, effs);
            const worstEff = Math.min.apply(null, effs);
            const avgEff = effs.reduce((s, v) => s + v, 0) / effs.length;
            const avgTH = throughputs.reduce((s, v) => s + v, 0) / throughputs.length;
            const avgWIP = wips.reduce((s, v) => s + v, 0) / wips.length;
            const spread = bestEff - worstEff;

            let performance = 'Explorer';
            if (bestEff > 75 && spread > 20) performance = 'Variability Analyst';
            if (bestEff > 85 && spread > 30) performance = 'Factory Physics Practitioner';
            if (bestEff > 92 && spread > 40) performance = 'Flow Master';

            const insights = [];
            if (spread > 30) {
                insights.push('You showed that the same average capacity produces very different throughput when variability, buffers, or CONWIP change.');
            } else {
                insights.push('Try larger swings between Low, Medium, and High variability to see the Variability Interaction Law in action.');
            }
            if (bestEff > 90) {
                insights.push('Excellent — you located a near-optimal configuration. Check whether CONWIP near W0 was involved.');
            } else {
                insights.push('Keep exploring: try CONWIP On at a limit of 4-6 with medium variability and buffers of 3-5.');
            }
            insights.push('Remember Little\u0027s Law: WIP = TH x CT. Every configuration you tested obeys it.');

            return {
                bestEfficiency: bestEff,
                worstEfficiency: worstEff,
                avgEfficiency: avgEff,
                avgThroughput: avgTH,
                avgWIP: avgWIP,
                efficiencySpread: spread,
                performance: performance,
                insights: insights
            };
        }

